6` (1.0 in Q8.8). Others 0.\n    //         - Loop `iter` from 0 to N (e.g., 50 or 100).\n    //           For each `s` (0-80):\n    //             Read `V[s]`.\n    //             Read `T[s]` (NextH, NextT).\n    //             Calculate `term_H = (V[s] * P_H) >> 10`.\n    //             Calculate `term_T = (V[s] * P_T) >> 10`.\n    //             Add to `V_next[NextH]` and `V_next[NextT]`.\n    //           Handle Absorbing states (Win, Lose, Draw) separately (they persist).\n    //           Swap `V` and `V_next`.\n    //      5. FINISH:\n    //         - Result = `V[Win_State_Index]`.\n    //    \n    //    Edge Cases:\n    //    - If G or K are length 0? Assume length >= 1.\n    //    - If patterns overlap? KMP handles this.\n    //    - If P=0 or P=1000.\n    //    \n    //    Hardware Implementation:\n    //    - We need memories: `V`, `V_next`, `T`.\n    //      `V`: 256 x 16 bits.\n    //      `T`: 81 x 16 bits (8 bits NextH, 8 bits NextT).\n    //      We can combine `T` and failure function storage.\n    //    \n    //    Timing:\n    //    PRECOMP: \n    //      Compute Pi: O(Len^2) or O(Len). Len=8. Fast.\n    //      Compute Transitions: 81 * 2 * (loop for failure) = small.\n    //      Let's say 500 cycles.\n    //    SOLVE:\n    //      50 iterations * 81 states = 4050 updates.\n    //      Each update: Read V, Read T, Mult, Shift, Add to V_next.\n    //      We can pipeline this or do 1 per cycle.\n    //      4050 cycles.\n    //    Total ~4550 cycles. Fits in 10,000.\n    //    \n    //    Refinements:\n    //    - Use 100 iterations for better accuracy. 8100 cycles.\n    //      Total ~8600 cycles. Still fits.\n    //    - Use 1000 iterations? No, too slow.\n    //      The problem says \"1000 iterations or...\". Maybe 100 is enough for convergence.\n    //      We will use 100 iterations.\n    //    \n    //    Multiplier:\n    //    `V[s]` (16 bits) * `P` (10 bits) = 26 bits.\n    //    Result = 26-bit >> 10 = 16 bits.\n    //    We can use a standard multiplier or accumulate in a wider register.\n    //    \n    //    Memory:\n    //    We need dual-port RAM for `V` to read/write in same cycle or separate read/write cycles.\n    //    We can use simple logic with registers if we unroll, but 256 registers is too much for LUTs.\n    //    Use Block RAM inferred logic.\n    //    \n    //    Verilog Implementation details:\n    //    - `V` and `V_next` arrays.\n    //    - `T` array (packed logic).\n    //    - Iteration counters.\n    //    - Finite State Machine for PRECOMP and SOLVE.\n    //    - KMP logic for Pi calculation.\n    //    - Transition logic for `T` calculation.\n    //    \n    //    Let's write the code.\n\n    // --- Internal Registers/Memories ---\n    // Probability Vector (Current and Next)\n    // We use two memories for ping-pong buffering to avoid read-after-write hazards during updates\n    // and to simplify the swap.\n    reg [15:0] V [0:255];      // Current probabilities\n    reg [15:0] V_next [0:255]; // Next iteration probabilities\n\n    // Transition Table (for transient states 0-80)\n    // packed: {next_state_T[7:0], next_state_H[7:0]}\n    reg [15:0] T_table [0:80];\n\n    // Helper registers for computation\n    reg [7:0] idx;              // General index (0-80 for states, 0-8 for lengths)\n    reg [7:0] idx_h, idx_t;     // Indices for H/T transitions\n    reg [15:0] prob_val;        // V[s]\n    reg [15:0] prod_h, prod_t;  // Products\n    reg [15:0] accum_h, accum_t; // Accumulators for V_next\n    \n    // KMP Pi arrays (local parameters for G and K)\n    // Max length 8, so index 0-7. We store pi[1...len]. pi[0] is 0.\n    reg [3:0] pi_g [0:7];\n    reg [3:0] pi_k [0:7];\n    \n    // Iteration control\n    reg [9:0] iter_cnt; // 0 to 1000\n    localparam MAX_ITER = 100;\n\n    // --- KMP Precomputation Logic ---\n    // We need to compute Pi for G and K.\n    // Since G/K are inputs, we do this in PRECOMP state.\n    // We will use a small loop inside PRECOMP state.\n    \n    // --- Transition Calculation Logic ---\n    // Given `lg` (0-8) and `lk` (0-8), and bit `b` (0 or 1), compute next `lg` and `lk`.\n    // We need to check G[lg] vs bit. G is `g_reg`. Bit 0 is LSB.\n    // G[0] is bit 0 of g_reg.\n    // \n    // Logic for next state:\n    // Function next_len(current_len, bit, pattern, pi):\n    //   while (current_len > 0 && pattern[current_len] != bit):\n    //     current_len = pi[current_len - 1];\n    //   if (pattern[current_len] == bit):\n    //     current_len++;\n    //   return current_len;\n    // \n    // We need to implement this loop in hardware (unrolled or sequential).\n    // Since max len is 8, a sequential loop is fine (max 8 iterations).\n\n    // --- State Definitions ---\n    localparam [3:0] S_IDLE      = 4'd0;\n    localparam [3:0] S_CHECK     = 4'd1;\n    localparam [3:0] S_PI_COMP   = 4'd2;\n    localparam [3:0] S_TRANS_PRE = 4'd3; // Prepare transition calc\n    localparam [3:0] S_TRANS_COM = 4'd4; // Compute transition\n    localparam [3:0] S_TRANS_WR  = 4'd5; // Write transition\n    localparam [3:0] S_ITER_INIT = 4'd6;\n    localparam [3:0] S_ITER_LOOP = 4'd7; // Outer loop (iterations)\n    localparam [3:0] S_ITER_UPDT = 4'd8; // Inner loop (states)\n    localparam [3:0] S_ITER_SWAP = 4'd9;\n    localparam [3:0] S_ITER_CLR  = 4'd10; // Clear V_next\n    localparam [3:0] S_FINISH    = 4'd15;\n\n    reg [3:0] sub_state, next_sub_state;\n\n    // Temporary variables for transition calculation\n    reg [2:0] temp_lg, temp_lk; // Current lengths being computed\n    reg [2:0] temp_lg_next, temp_lk_next;\n    reg [2:0] bit_val; // 0 or 1\n    reg [1:0] calc_step; // 0: H, 1: T\n    reg [2:0] loop_idx; // For the failure function loop\n    \n    // --- Main FSM ---\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            sub_state <= S_IDLE;\n            done <= 1'b0;\n            result <= 16'd0;\n            // Clear V and V_next\n            for (int i = 0; i < 256; i = i + 1) begin\n                V[i] <= 16'd0;\n                V_next[i] <= 16'd0;\n            end\n            // Clear T_table\n            for (int i = 0; i < 81; i = i + 1) begin\n                T_table[i] <= 16'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        g_reg <= g_arr;\n                        k_reg <= k_arr;\n                        p_reg <= P;\n                        state <= CHECK_SAME;\n                    end\n                end\n\n                CHECK_SAME: begin\n                    if (same_pattern) begin\n                        result <= 16'd0;\n                        state <= FINISH;\n                    end else begin\n                        state <= PRECOMP;\n                        sub_state <= S_PI_COMP;\n                        idx <= 0; // Initialize Pi index\n                    end\n                end\n\n                PRECOMP: begin\n                    case (sub_state)\n                        S_PI_COMP: begin\n                            // Compute KMP Pi for G and K\n                            // We use `idx` as the length index (1 to 8)\n                            // Logic for pi[i]: compare G[i] with G[pi[i-1]], etc.\n                            // Since max len 8, we unroll logic or use simple loop.\n                            // Here we compute sequentially.\n                            // pi[0] = 0 (implicit)\n                            if (idx < 8) begin\n                                // Compute pi_g[idx+1] (since idx 0->len 1)\n                                // Actually, let's index pi by length 1..8\n                                // idx is 0..7 corresponding to length 1..8\n                                // We need a temp variable for the loop.\n                                // To keep it simple and combinational, we compute one step per cycle.\n                                // But computing Pi requires a loop.\n                                // Let's use a dedicated sub-sub state for Pi calculation or compute it in combinational block.\n                                // Given the small size, we can compute it in a combinational block triggered by PRECOMP.\n                                // However, we are in a sequential block.\n                                // Let's move Pi calculation to a combinational logic at the end of PRECOMP.\n                                // Or, just compute it once using a static loop (unrolled) inside PRECOMP state.\n                                \n                                // Unrolled computation (pseudocode):\n                                // pi_g[0] = 0;\n                                // for i=1..7:\n                                //   j = pi_g[i-1];\n                                //   while (j>0 && G[i]!=G[j]) j = pi_g[j-1];\n                                //   if (G[i]==G[j]) j++;\n                                //   pi_g[i] = j;\n                                \n                                // Since we can't have loops in always blocks easily without state machines, \n                                // we will use a loop variable `loop_idx` and update it.\n                                // But `pi_g` is a reg array. We can write to it.\n                                // Let's use a separate state for each i calculation.\n                                // Since 8 iterations, it's fast.\n                                \n                                // Actually, let's just set sub_state to TRANS_PRE and compute Pi on the fly inside TRANS_COM.\n                                // No, we need Pi for transition calculation.\n                                // Let's hardcode the Pi calculation logic for 8 bits using a `for` loop inside an always block.\n                                // Icarus Verilog supports `for` loops in generate or combinational blocks if unrolled.\n                                // Let's try a `for` loop in combinational logic.\n                                // We'll define a combinational block that computes `pi_g` and `pi_k` whenever `g_reg` or `k_reg` changes.\n                                // But they are stable in PRECOMP.\n                                // Let's just do the calculation in PRECOMP state with a small counter.\n                                \n                                // We need to compute `pi_g` and `pi_k` fully before transitioning to TRANS_PRE.\n                                // We can do this in 8 cycles.\n                                // Let's use `idx` as the length being computed (1 to 8).\n                                // `loop_idx` will be the inner loop counter (j).\n                                \n                                // This is getting complex for a simple state machine.\n                                // Let's assume we compute Pi in a combinational block at the start of PRECOMP.\n                                // Since inputs are stable, we can do:\n                                // always @(*) begin compute_pi(g_reg, pi_g); end\n                                // But we need to write to `pi_g` array. Reg arrays can't be assigned in always @(*) if they are outputs of logic.\n                                // We can use temporary variables.\n                                \n                                // Let's use a dedicated logic block for Pi.\n                                // We will move to TRANS_PRE and compute transitions. \n                                // Wait, we need Pi to compute transitions.\n                                // \n                                // Let's use a helper combinational block to compute Pi.\n                                // Since Icarus Verilog might have issues with unpacked array outputs, we will compute it sequentially.\n                                // We'll stay in S_PI_COMP for 16 cycles (8 for G, 8 for K).\n                                \n                                // Logic for step `idx` (0 to 7):\n                                // Compute pi_g[idx] and pi_k[idx].\n                                // We need the `while` loop logic. \n                                // Since max len is 8, the while loop runs at most 8 times.\n                                // We can flatten it or use a state machine.\n                                // To save time, let's use a flattened logic for small N.\n                                // But Verilog doesn't support dynamic loops in synthesis.\n                                // \n                                // Let's use a `generate` block? No, inputs change.\n                                // \n                                // Fallback: Compute transitions without Pi (Brute force check).\n                                // For each state (lg, lk) and bit:\n                                //   Try `lg+1`, `lg`, `lg-1`... down to 0.\n                                //   Check if G matches suffix.\n                                //   This is O(Len) per check.\n                                //   81 states * 2 bits * 8 checks * 8 comparisons = ~10k ops. Fits in PRECOMP time.\n                                //   This avoids storing Pi.\n                                //   Let's do this. It's simpler and robust.\n                                //   \n                                //   Revised PRECOMP strategy:\n                                //   Iterate `lg` (0-8), `lk` (0-8).\n                                //   For each, calculate transitions for H and T.\n                                //   To calculate transition for `lg`, `bit`:\n                                //     Check `lg+1`: does G[lg] == bit? (If `lg` < 8).\n                                //     If yes, `next_lg = lg+1`.\n                                //     Else: Check `lg`, `lg-1` ... 0.\n                                //       For `len` = `lg` down to 0:\n                                //         Check if G[`len-1`...0] matches `bit` + history.\n                                //         Wait, we don't have history bits in state `{lg, lk}`.\n                                //         The state `{lg, lk}` ONLY stores the length of the match.\n                                //         If we lose the match, we need to know the history to find the new match length.\n                                //         This is why we need the failure function (Pi).\n                                //         Without Pi, we cannot transition from a high `lg` to a lower `lg` deterministically just by knowing `lg`.\n                                //         We need the actual bits or the failure function.\n                                //         \n                                //         So we MUST compute Pi.\n                                //         \n                                //         Let's compute Pi using a simple sequential loop.\n                                //         We'll use `idx` (0-7) for the length index.\n                                //         We'll use `loop_idx` as the temporary `j`.\n                                //         \n                                //         State S_PI_COMP:\n                                //           if (idx < 8) begin\n                                //             // Compute pi_g[idx]\n                                //             // We need to compare G[idx] with G[j]\n                                //             // We can't do while loop. We can unroll the while loop because max depth is small.\n                                //             // Or, we can use a combinational block to compute Pi given G.\n                                //             // Let's try a combinational block for Pi.\n                                //             // We will define a function or combinational always block that updates `pi_g` and `pi_k`.\n                                //             // Since we are in PRECOMP, we can compute Pi once and store it.\n                                //             // We'll use a combinational block `compute_pi` triggered by `state == PRECOMP`.\n                                //             // But `pi_g` is a reg array. We can't assign it in comb logic easily.\n                                //             // We can use temporary wires and then load them into regs.\n                                //           end\n                                //         \n                                //         Let's simplify: \n                                //         We will compute transitions in a combinational block during PRECOMP.\n                                //         The combinational block will compute `next_lg` and `next_lk` for all 81 states.\n                                //         We then load `T_table` from these combinational values.\n                                //         \n                                //         Combinational block:\n                                //         For each state `s` (lg, lk):\n                                //           For H and T:\n                                //             Calculate `next_lg` using `compute_next_len(g_reg, lg, bit)`.\n                                //             Calculate `next_lk` using `compute_next_len(k_reg, lk, bit)`.\n                                //             Determine absorption.\n                                //             Encode next state index.\n                                //         \n                                //         `compute_next_len`:\n                                //           input: pattern, current_len, bit.\n                                //           output: next_len.\n                                //           Logic: \n                                //             if (current_len < 8 && pattern[current_len] == bit) return current_len + 1;\n                                //             else if (current_len > 0) return pi[current_len - 1] (recursive? no, iterative).\n                                //             else return 0.\n                                //           Since we don't have Pi, we can simulate the failure loop by checking all shorter prefixes.\n                                //           This takes O(Len) logic.\n                                //           \n                                //           Logic for `next_len`:\n                                //             if (current_len < 8 && pattern[current_len] == bit) next_len = current_len + 1;\n                                //             else begin\n                                //               // Find longest proper prefix which is also suffix\n                                //               // We check lengths from current_len-1 down to 0\n                                //               // This requires a loop in comb logic. We can unroll it.\n                                //               // However, Verilog doesn't allow loops in comb logic that depend on variables.\n                                //               // We can use `if-else` chain or `case`.\n                                //               // Since max len 8, we can unroll manually or use a for loop in a generate block (but inputs are dynamic).\n                                //               // Actually, we can do this:\n                                //               // For `k` from `current_len-1` downto 0:\n                                //               //   Check if pattern[0:k-1] matches `bit` + suffix of history.\n                                //               //   Wait, we don't have history!\n                                //               //   \n                                //               // The problem with state `{lg, lk}` is exactly this: \n                                //               // When match fails, we don't know what to fallback to unless we precompute failure links.\n                                //               // So we MUST compute failure links (Pi).\n                                //               // \n                                //               // Let's compute Pi in a combinational block using unrolled `if` statements.\n                                //               // For `len` from 1 to 8:\n                                //               //   pi[len] = ...\n                                //               //   We need to check `pattern[len-1] == pattern[j-1]` where `j` is the previous pi.\n                                //               //   This is a loop. We can unroll it because `len` is fixed in the generate block.\n                                //               //   But pattern is input.\n                                //               //   \n                                //               // Let's use a `generate` block to instantiate logic for each `len`.\n                                //               // This is robust but verbose.\n                                //               // \n                                //               // Alternative: \n                                //               // Since we have 10,000 cycles, we can compute transitions sequentially.\n                                //               // State S_TRANS_COM:\n                                //               //   We are at state `(lg, lk)`.\n                                //               //   We need to compute `next_lg_H`, `next_lg_T`.\n                                //               //   We can compute these using a small loop (max 8 iterations) inside the FSM.\n                                //               //   This will take 8 cycles per state.\n                                //               //   81 states * 8 cycles * 2 bits = 1296 cycles. \n                                //               //   This is acceptable.\n                                //               //   \n                                //               //   So, PRECOMP will iterate `lg` 0-8, `lk` 0-8.\n                                //               //   For each `(lg, lk)`, we compute transitions for H and T.\n                                //               //   To compute transition for `lg`, `bit`:\n                                //               //     We need Pi for G.\n                                //               //     We can compute Pi for G once (8 cycles).\n                                //               //     Compute Pi for K once (8 cycles).\n                                //               //     Then use Pi to compute transitions (81 * 2 * small logic).\n                                //               //     \n                                //               //   Let's do:\n                                //               //   1. Compute `pi_g` (8 cycles).\n                                //               //   2. Compute `pi_k` (8 cycles).\n                                //               //   3. Compute `T_table` (81 states).\n                                //               //   \n                                //               //   How to compute Pi sequentially?\n                                //               //   We can't easily do the while loop in hardware sequentially without a state machine.\n                                //               //   But we can unroll the while loop for max depth 8.\n                                //               //   \n                                //               //   Let's use a combinational block for Pi computation that is triggered by `g_reg` and `k_reg`.\n                                //               //   We'll declare `pi_g_wire` and `pi_k_wire` as outputs of a comb block.\n                                //               //   Then in PRECOMP, we load them into `pi_g` and `pi_k` registers.\n                                //               //   \n                                //               //   Combinational Pi Logic:\n                                //               //   always @(*) begin\n                                //               //     pi_g_wire[0] = 0;\n                                //               //     for (int i = 1; i < 8; i++) begin\n                                //               //       int j = pi_g_wire[i-1];\n                                //               //       while (j > 0 && g_reg[i] != g_reg[j]) j = pi_g_wire[j-1];\n                                //               //       if (g_reg[i] == g_reg[j]) j++;\n                                //               //       pi_g_wire[i] = j;\n                                //               //     end\n                                //               //   end\n                                //               //   This `while` loop is not synthesizable directly in always @(*) in some tools.\n                                //               //   But since depth is small, we can unroll it or use a generate block.\n                                //               //   \n                                //               //   Let's assume we can use a `for` loop in comb logic for Pi (Icarus supports it if unrolled).\n                                //               //   We'll do it in a separate always block.\n                                //               //   \n                                //               //   Once we have Pi, computing next state is easy:\n                                //               //   if (lg < 8 && g_reg[lg] == bit) next_lg = lg + 1;\n                                //               //   else if (lg > 0) next_lg = pi_g[lg-1]; // This is the first step. But we might need to repeat.\n                                //               //   Actually, `pi` gives the length of the longest proper prefix which is also suffix.\n                                //               //   So `next_len` is `pi[lg-1]` (if match fails at lg).\n                                //               //   But we need to check if `pi[lg-1]` matches `bit`?\n                                //               //   No, `pi` is precomputed for the pattern itself.\n                                //               //   Wait, standard KMP transition:\n                                //               //   `next_len = transition[current_len][bit]`.\n                                //               //   This transition table is what we are computing!\n                                //               //   We are building the transition table of the automaton.\n                                //               //   \n                                //               //   So we are circular: we need Pi to build transitions, but transitions are the goal.\n                                //               //   The standard way to build the transition table is:\n                                //               //   For `len` from 0 to 8:\n                                //               //     For `bit` in {0, 1}:\n                                //               //       if (len < 8 && g_reg[len] == bit) transition[len][bit] = len + 1;\n                                //               //       else if (len == 0) transition[len][bit] = 0;\n                                //               //       else transition[len][bit] = transition[pi[len-1]][bit];\n                                //               //   \n                                //               //   This requires `transition` table to be filled progressively.\n                                //               //   Since we only have 8 lengths, we can compute it in a loop.\n                                //               //   \n                                //               //   Let's implement this logic in the FSM.\n                                //               //   We will compute `trans_g[len][bit]` and `trans_k[len][bit]` first.\n                                //               //   Then combine them for the joint state `(lg, lk)`.\n                                //               //   \n                                //               //   Storage: \n                                //               //   `trans_g`: 9 states (0-8) * 2 bits = 18 entries. 4 bits each (0-8). 36 bits total.\n                                //               //   `trans_k`: same.\n                                //               //   \n                                //               //   Steps in PRECOMP:\n                                //               //   1. Compute `pi_g`, `pi_k`. (Combinational or sequential).\n                                //               //   2. Compute `trans_g` (0-8) and `trans_k` (0-8).\n                                //               //   3. Compute `T_table` (0-80) by combining `trans_g` and `trans_k`.\n                                //               //   \n                                //               //   This is efficient and deterministic.\n                                //               //   Let's go with this.\n                                //               //   \n                                //               //   We'll use combinational logic to compute Pi and Trans.\n                                //               //   Then load them into registers in PRECOMP state.\n                                //               //   \n                                //               //   Memory for `trans_g`: reg [3:0] trans_g [0:8][0:1];\n                                //               //   But unpacked arrays are tricky.\n                                //               //   Use packed: reg [17:0] trans_g; // {next8, next7, ..., next0} for bit 0, then bit 1?\n                                //               //   Or just compute on the fly.\n                                //               //   \n                                //       